P.QBANK = ["Que me révèle ce passage sur le caractère de Dieu ?","Quels traits de ma vieille nature, centrée sur moi-même, ce passage met-il en lumière en moi ?","Si je laisse Jésus régner sur cette situation, que ferais-je ?","Quel exemple le Seigneur Jésus me donne-t-il ici ?","Quel pas le Saint-Esprit m’invite-t-il à faire aujourd’hui par cette Parole ?","Pourquoi les personnes de ce passage ont-elles échoué ? La racine était-elle l’orgueil ou la peur ?","Comment ce passage m’aide-t-il à vivre le Wu Ji (le renoncement à soi-même) ?","Dans quelle relation puis-je mettre ce passage en pratique ?","Quel lien y a-t-il entre ce passage et la demande du Notre Père : « Que ton règne vienne » ?","Donnez-moi une image de la vie quotidienne pour comprendre le cœur de ce passage."];
P.QAUD = {"seeker":["Quel rapport y a-t-il entre ce passage et ma vie d’aujourd’hui ?","Je ne pratique pas encore la foi chrétienne. Que peuvent signifier ces paroles pour moi ?","Dieu existe-t-il vraiment ? Quelles raisons a-t-on de croire ?","Pourquoi la Bible dit-elle que chacun a besoin de Jésus ?","Je vis beaucoup de stress. Quelle aide concrète la Bible peut-elle m’apporter ?","Que signifie ici le mot « péché » ? Cela me concerne-t-il ?","Les chrétiens parlent sans cesse de « grâce ». Qu’est-ce que c’est, en termes simples ?","Si je veux en savoir plus, par où commencer ?"],"teen":["Quel rapport y a-t-il entre ce passage et mon quotidien : le lycée, mes amis, mon téléphone ?","Si ce passage était un message de Dieu rien que pour moi, que dirait-il ?","Tout le monde le fait. Est-ce bizarre de ne pas le faire ? Que dit l’Écriture ?","Pouvez-vous m’expliquer ce passage avec un jeu vidéo ou un film ?","Qu’y a-t-il de surprenant ou de peu connu dans ce passage ?","La pression des examens est énorme. Quelle force ce passage me donne-t-il ?","J’ai du mal à pardonner à quelqu’un. Comment ce passage m’aide-t-il ?","Dieu me voit-il vraiment ? Qu’est-ce qui fait que je mérite l’amour ?"],"kid":["De quoi parle cette histoire ? Pouvez-vous me la raconter ?","Qu’est-ce que Dieu a fait dans cette histoire ?","Est-ce que Jésus m’aime ? Comment le savoir ?","Qui est le plus courageux dans cette histoire ? Pourquoi ?","Comment puis-je être comme les personnages de cette histoire ?","Apprenez-moi un verset court que je pourrai retenir par cœur.","Je me suis fâché avec mon meilleur ami. Que ferait Jésus ?","Pouvez-vous m’apprendre une toute petite prière ?"]};
P.AUD2 = {"elder":{"q":["Avec les mots les plus simples, que dit ce passage ?","Quelle consolation ce passage apporte-t-il aux personnes âgées ?","Mon corps s’affaiblit. Comment Dieu prend-il soin de moi ?","Je ressens souvent de la solitude. Que m’apporte ce passage ?","Comment transmettre ma foi à mes enfants et petits-enfants ?","Il y a des choses que je n’arrive pas à lâcher. Comment ce passage m’apprend-il à les confier au Seigneur ?","J’ai déjà un grand âge. Que puis-je encore faire pour Dieu ?","Écrivez-moi, s’il vous plaît, une courte prière que je pourrai présenter au Seigneur."],"fu":["Santé","Solitude","Famille","Confiance","Espérance","Prière"],"rw":["Vous avez terminé tout le livre de {nm} !","Jour après jour, vous avez cheminé jusqu’ici. Dieu se souvient de cette fidélité, et c’est un exemple pour les plus jeunes."],"res":["Ne vous inquiétez pas, nous avançons doucement. En le relisant, le sens deviendra plus clair.","Très bien ! Vous vous souvenez de beaucoup de choses de ce chapitre.","Magnifique ! La Parole de Dieu vit dans votre cœur."]},"single_parent":{"q":["Je porte la charge de la famille sans aide. Quelle consolation ce passage m’apporte-t-il ?","Je suis à bout de forces et j’ai l’impression de ne pas en faire assez pour mes enfants. Comment Dieu me voit-il ?","Comment Dieu prend-il soin des orphelins et des veuves, et que cela signifie-t-il pour moi ?","L’argent manque cruellement. Que m’apporte ce passage ?","Mon enfant me répond mal et ses émotions sont très vives. Que dois-je faire ?","Je ne sais pas comment dire à mon enfant que son père (ou sa mère) n’est pas avec nous.","Je ressens une grande solitude. Comment demander de l’aide à l’Église ou à mes frères et sœurs en la foi ?","Écrivez-moi, s’il vous plaît, une courte prière que je pourrai dire en cinq minutes."],"fu":["Fatigue","Enfants","Argent","Demander de l’aide","Espérance","Prière"],"rw":["Vous avez terminé tout le livre de {nm} !","Ce n’est pas facile de continuer à lire la Bible quand on élève sa famille sans soutien. Dieu voit chacun de vos pas, et il est avec vous."],"res":["Ne vous inquiétez pas, vous avez fait un grand effort. Relisez-le quand vous aurez un moment.","Très bien ! Vous retenez beaucoup, malgré vos journées si chargées.","Magnifique ! La Parole de Dieu vous soutient."]},"single":{"q":["En tant que célibataire, que me dit ce passage ?","Je ressens de la solitude. Que m’apporte ce passage ?","Qui suis-je en Christ, et quelle est ma valeur ?","Comment faire confiance à Dieu pendant que j’attends ?","Quelle sagesse la Bible offre-t-elle sur les relations ?","Comment le temps et les forces d’une personne célibataire peuvent-ils être mis au service de Dieu ?","Comment construire de belles relations dans l’Église et avec mes amis ?","Écrivez-moi, s’il vous plaît, une courte prière pour une personne célibataire."],"fu":["Solitude","Identité","Attente","Relations","Sens de la vie","Prière"],"rw":["Vous avez terminé tout le livre de {nm} !","Vous avez avancé par vous-même, et devant Dieu vos jours sont pleins et aimés."],"res":["Ne vous inquiétez pas, nous avançons doucement. En le relisant, le sens deviendra plus clair.","Très bien ! Vous avez saisi l’essentiel de ce chapitre.","Excellent ! Vous persévérez, et la Parole de Dieu prend racine en vous."]},"parent":{"q":["En tant que parent, que me rappelle ce passage ?","Mon enfant ne m’écoute pas et ses émotions sont très vives. Comment dois-je réagir ?","Comment concilier discipline et grâce ?","Comment bien communiquer avec un enfant adolescent ?","Je m’emporte souvent contre mon enfant, puis je me sens coupable. Que faire ?","Comment guider mon enfant pour qu’il connaisse Dieu et ne se contente pas d’aller à l’église ?","Mon conjoint et moi ne sommes pas d’accord sur la manière d’éduquer notre enfant. Que dit ce passage ?","Écrivez-moi, s’il vous plaît, une courte prière de bénédiction pour mon enfant."],"fu":["Dialogue","Discipline","Conscience","Couple","Foi","Prière"],"rw":["Vous avez terminé tout le livre de {nm} !","Lire l’Écriture chaque jour au milieu de l’agitation de l’éducation des enfants est le plus bel exemple que vous puissiez leur donner."],"res":["Ne vous inquiétez pas, nous avançons doucement. Relisez-le quand vous en aurez l’occasion.","Très bien ! Vous avez saisi l’essentiel de ce chapitre.","Magnifique ! La Parole de Dieu prend racine dans votre foyer."]},"couple":{"q":["En tant que couple, que nous dit ce passage ?","Après chaque dispute, nous nous refroidissons. Comment l’un de nous peut-il faire le premier pas vers la réconciliation ?","Comment exprimer ce que je ressens pour que mon conjoint m’écoute ?","Mon conjoint m’a fait du mal. Dois-je vraiment pardonner ?","Nous ne sommes pas d’accord sur l’argent ni sur les tâches ménagères. Que faire ?","Comment prier ensemble et nous approcher de Dieu en couple ?","Nous nous sommes éloignés à cause du rythme de la vie. Comment nous rapprocher à nouveau ?","Écrivez-nous, s’il vous plaît, une courte prière de bénédiction pour notre mariage."],"fu":["Dialogue","Pardon","Complicité","Un seul cœur","Lecture à deux","Prière"],"rw":["Vous avez terminé ensemble tout le livre de {nm} !","Un couple qui s’approche ensemble de la Parole de Dieu s’appuie sur un fondement solide."],"res":["Ne vous inquiétez pas, nous avançons doucement. Relisez-le ensemble un de ces soirs.","Très bien ! Vous avez tous deux saisi l’essentiel de ce chapitre.","Magnifique ! La Parole de Dieu prend racine dans votre mariage."]},"pastor":{"q":["Dans le service du Seigneur, que me dit ce passage ?","Aidez-moi à trouver un plan de message et un point de départ pour ce passage.","Je suis au bord de l’épuisement. Quelle consolation ce passage m’apporte-t-il ?","Comment faire face aux critiques et aux malentendus au sein de l’Église ?","Que dit ce passage sur la manière de conduire une équipe d’un même cœur ?","Comment entretenir ma relation personnelle avec Dieu au milieu d’un ministère si chargé ?","Comment prendre soin des faibles, des blessés et de ceux qui se sont éloignés de l’Église ?","Écrivez-moi, s’il vous plaît, une courte prière d’intercession pour l’Église et mes collaborateurs."],"fu":["Message","Accompagnement","Équipe","Repos","Combat spirituel","Intercession"],"rw":["Vous avez terminé tout le livre de {nm} !","Demeurer près de la Parole de Dieu au milieu d’un ministère chargé est la racine la plus profonde de tout service pastoral."],"res":["Ne vous inquiétez pas, nous avançons doucement. Relisez-le quand vous en aurez l’occasion.","Très bien ! Vous avez saisi l’essentiel de ce chapitre.","Magnifique ! La Parole de Dieu nourrit d’abord le pasteur, puis coule vers le troupeau."]}};
